<?php

declare(strict_types=1);

namespace Architex\Tests\Integration\Http;

use Architex\Http\AuthenticationKernelFactory;
use Architex\Http\Request;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Identity\PasswordResetNotifier;
use Architex\Platform\Identity\RegistrationNotifier;
use Architex\Platform\Identity\SessionService;
use Architex\Tests\Support\MariaDbTestCase;

final class RefuseCalculatorHttpTest extends MariaDbTestCase
{
    public function testGovernedRefuseRunIssuesExportsAndProjectActionsThroughAuthenticatedHttp():void
    {
        [$organisationId,$ownerId,$projectId]=$this->seedTenant();$notifier=new class implements RegistrationNotifier,PasswordResetNotifier{public function isAvailable():bool{return false;}public function send(string$email,string$token,string$expiresAt):void{}};$kernel=(new AuthenticationKernelFactory($this->pdo,$notifier,$notifier))->create();$session=(new SessionService($this->pdo))->rotate($ownerId);$headers=['Cookie'=>'architex_session='.$session->token,'X-Organisation-Id'=>$organisationId,'X-CSRF-Token'=>$session->csrfToken];
        $seedResponse=$kernel->handle($this->json('POST','/api/v1/compliance-rule-versions/seed',$headers,['ruleKey'=>'municipal_refuse']));self::assertSame(201,$seedResponse->status(),$seedResponse->body());$seed=$seedResponse->json()['data'];self::assertSame('municipal_refuse',$seed['ruleKey']);self::assertFalse($seed['issueEligible']);
        $candidateResponse=$kernel->handle($this->json('POST','/api/v1/compliance-rule-versions',$headers,['ruleKey'=>'municipal_refuse','version'=>'http-reviewed-refuse-1','sourceReference'=>'Disposable HTTP transcription of official municipal source','effectiveDate'=>'2026-08-28','rules'=>$seed['rules']]));self::assertSame(201,$candidateResponse->status(),$candidateResponse->body());$candidate=$candidateResponse->json()['data'];
        $verifiedResponse=$kernel->handle($this->json('POST','/api/v1/compliance-rule-versions/'.$candidate['id'].'/verify',$headers,['humanConfirmed'=>true,'verificationReason'=>'Exact disposable municipal source transcription reviewed.']));self::assertSame(200,$verifiedResponse->status(),$verifiedResponse->body());$verified=$verifiedResponse->json()['data'];
        $definitions=$kernel->handle(Request::json('GET','/api/v1/toolbox/definitions',$headers));self::assertContains('refuse_area_calculator',array_column($definitions->json()['data'],'id'));
        $input=['ruleVersionId'=>$verified['id'],'project'=>['projectName'=>'Refuse HTTP','reference'=>'REF-HTTP','climateZone'=>4,'buildingType'=>'residential','storeys'=>2,'floorArea'=>1200],'occupancyUse'=>'residential_dwelling','quantity'=>12,'collectionIntervalDays'=>7,'contingencyPercent'=>10,'binType'=>'standard_1100l','proposedStorageAreaM2'=>10,'facilities'=>['collectionVehicleAccess'=>true,'washdownWater'=>true,'drainage'=>false,'ventilation'=>true,'wasteSeparation'=>true],'assumptions'=>'Disposable HTTP evidence.','professionalConfirmation'=>['confirmed'=>true,'role'=>'architect_or_civil_engineer','responsibilityStatement'=>'I reviewed the exact source, inputs, calculation and limitations.']];
        $unconfirmed=$input;$unconfirmed['professionalConfirmation']['confirmed']=false;$rejected=$kernel->handle($this->json('POST','/api/v1/toolbox/runs',$headers,['toolId'=>'refuse_area_calculator','input'=>$unconfirmed,'assignment'=>['mode'=>'internal_project','projectId'=>$projectId],'issueImmediately'=>true,'issueReason'=>'Architect review.']));self::assertSame(422,$rejected->status(),$rejected->body());self::assertSame('professional_confirmation_required',$rejected->json()['error']['code']);
        $this->pdo->exec("UPDATE professional_profiles SET profession='quantity_surveyor'");$wrongProfession=$kernel->handle($this->json('POST','/api/v1/toolbox/runs',$headers,['toolId'=>'refuse_area_calculator','input'=>$input,'assignment'=>['mode'=>'internal_project','projectId'=>$projectId],'issueImmediately'=>true,'issueReason'=>'Wrong profession must fail closed.']));self::assertSame(422,$wrongProfession->status(),$wrongProfession->body());self::assertSame('professional_authority_not_verified',$wrongProfession->json()['error']['code']);$this->pdo->exec("UPDATE professional_profiles SET profession='architect'");
        $issuedResponse=$kernel->handle($this->json('POST','/api/v1/toolbox/runs',$headers,['toolId'=>'refuse_area_calculator','input'=>$input,'assignment'=>['mode'=>'internal_project','projectId'=>$projectId],'issueImmediately'=>true,'issueReason'=>'Architect reviewed the exact refuse evidence.']));self::assertSame(201,$issuedResponse->status(),$issuedResponse->body());$issued=$issuedResponse->json()['data'];self::assertSame('issued',$issued['status']);self::assertSame('fail',$issued['output']['verdict']);self::assertSame('architect',$issued['output']['professionalAuthority']['profileProfession']);self::assertMatchesRegularExpression('/\A[a-f0-9]{64}\z/',$issued['auditHash']);
        $exports=$kernel->handle(Request::json('GET','/api/v1/toolbox/runs/'.$issued['id'].'/exports',$headers));self::assertSame(200,$exports->status(),$exports->body());self::assertSame(['json','csv','html'],array_column($exports->json()['data'],'format'));self::assertSame(1,(int)$this->pdo->query("SELECT COUNT(*) FROM project_records WHERE module_key='toolbox' AND record_type='tool_run'")->fetchColumn());self::assertSame(2,(int)$this->pdo->query("SELECT COUNT(*) FROM inbox_items WHERE event_type='compliance_action'")->fetchColumn());self::assertSame(3,(int)$this->pdo->query("SELECT COUNT(*) FROM audit_events WHERE action LIKE 'compliance_rule.%' OR action LIKE 'tool_run.%'")->fetchColumn());
    }

    /** @return array{string,string,string} */
    private function seedTenant():array{$organisationId=Identifier::generate();$ownerId=Identifier::generate();$reviewerId=Identifier::generate();$projectId=Identifier::generate();$this->pdo->prepare("INSERT INTO users(id,email,password_hash,status,email_verified_at) VALUES(UNHEX(:owner),'refuse-http-owner@example.test','hash','active',UTC_TIMESTAMP(6)),(UNHEX(:reviewer),'refuse-http-reviewer@example.test','hash','active',UTC_TIMESTAMP(6))")->execute(['owner'=>$ownerId,'reviewer'=>$reviewerId]);$this->pdo->prepare("INSERT INTO organisations(id,name,slug,status) VALUES(UNHEX(:id),'Refuse HTTP',:slug,'active')")->execute(['id'=>$organisationId,'slug'=>'refuse-http-'.substr($organisationId,0,8)]);$this->pdo->prepare("INSERT INTO organisation_memberships(id,organisation_id,user_id,role,status) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:user),'owner','active')")->execute(['id'=>Identifier::generate(),'organisation'=>$organisationId,'user'=>$ownerId]);$this->pdo->prepare("INSERT INTO professional_profiles(id,organisation_id,user_id,display_name,profession,bio,service_areas) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:user),'Verified Architect','architect','HTTP test profile','[]')")->execute(['id'=>Identifier::generate(),'organisation'=>$organisationId,'user'=>$ownerId]);$this->pdo->prepare("INSERT INTO verification_records(id,organisation_id,user_id,kind,grade,registration_body,registration_number,popia_consent_at,processing_purpose,retention_until,reviewed_by,reviewed_at) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:user),'professional_registration','manually_reviewed','SACAP','REF-HTTP-ARCH',UTC_TIMESTAMP(6),'Refuse calculator HTTP authority test',DATE_ADD(UTC_DATE(),INTERVAL 1 YEAR),UNHEX(:reviewer),UTC_TIMESTAMP(6))")->execute(['id'=>Identifier::generate(),'organisation'=>$organisationId,'user'=>$ownerId,'reviewer'=>$reviewerId]);$this->pdo->prepare("INSERT INTO projects(id,organisation_id,project_code,project_name,client_name,municipality,property_reference,property_use,land_use_notes,lead_professional_role,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),'REF-HTTP','Refuse HTTP','Client','Tshwane','Erf 80','Residential','','architect',UNHEX(:user))")->execute(['id'=>$projectId,'organisation'=>$organisationId,'user'=>$ownerId]);return[$organisationId,$ownerId,$projectId];}
    /** @param array<string,string>$headers @param array<string,mixed>$body */private function json(string$method,string$path,array$headers,array$body):Request{return Request::json($method,$path,$headers+['Content-Type'=>'application/json'],json_encode((object)$body,JSON_THROW_ON_ERROR));}
}
